"""Generate src/font.ts from python/act1033led/font.py (the single source of truth for the 5x7 Polish font)."""
import json
import pathlib
import sys

root = pathlib.Path(__file__).resolve().parents[2]
sys.path.insert(0, str(root / "python"))
from act1033led import font  # noqa: E402

glyphs = {ch: [w, {str(y): r for y, r in rows.items()}] for ch, (w, rows) in font.GLYPHS.items()}
out = (
    "// generated by tools/gen_font.py from python/act1033led/font.py - do not edit\n"
    "// GLYPHS: char -> [width, { row: \"#..#.\" }]; row 0 = top of capitals, 6 = baseline, 7-8 = descenders, -2..-1 = capital accents\n"
    f"export const GLYPHS: Record<string, [number, Record<string, string>]> = {json.dumps(glyphs, ensure_ascii=False)};\n"
    f"export const BASE: Record<string, string> = {json.dumps(font.BASE, ensure_ascii=False)};\n"
)
(root / "cloudflare" / "src" / "font.ts").write_text(out, encoding="utf-8")
print("glyphs:", len(glyphs))
